import { Component } from '@angular/core';
import { ContactService } from '../../services/contact.service';
import { ContactMessage } from '../../Modals/EkartModels';

@Component({
  selector: 'app-contact',
  templateUrl: './contact.component.html',
  styleUrls: ['./contact.component.css']
})
export class ContactComponent {
  formData: ContactMessage = {
    name: '',
    email: '',
    subject: '',
    message: ''
  };

  submitted = false;
  successMessage = '';
  errorMessage = '';

  constructor(private contactService: ContactService) {}

  onSubmit() {
    if (!this.formData.name || !this.formData.email || !this.formData.message) {
      this.errorMessage = 'Please fill out all required fields.';
      return;
    }

    this.errorMessage = '';
    this.contactService.submitContact(this.formData).subscribe(res => {
      if (res.success) {
        this.submitted = true;
        this.successMessage = res.message;
        this.formData = { name: '', email: '', subject: '', message: '' };
      } else {
        this.errorMessage = res.message || 'Failed to submit message.';
      }
    });
  }
}
<div class="contact-page">
  <div class="contact-header">
    <h1>Get In <span class="highlight">Touch</span></h1>
    <p>Have questions about your order, products, or exchanges? We are here to help!</p>
  </div>

  <div class="contact-grid">
    <div class="info-cards">
      <div class="info-card">
        <span class="info-icon">📍</span>
        <div>
          <h4>Corporate Headquarters</h4>
          <p>eKart Tech Park, Silicon Valley Cyber Towers, Bengaluru, 560001</p>
        </div>
      </div>
      <div class="info-card">
        <span class="info-icon">📞</span>
        <div>
          <h4>Phone Support</h4>
          <p>+1 (800) 555-EKART / +91 8000-123-456</p>
          <p class="sub-text">Mon - Sat: 9:00 AM - 8:00 PM IST</p>
        </div>
      </div>
      <div class="info-card">
        <span class="info-icon">✉️</span>
        <div>
          <h4>Email Support</h4>
          <p>support@ekart.com / returns@ekart.com</p>
        </div>
      </div>
    </div>

    <div class="form-container">
      <h3>Send Us a Message</h3>
      <div class="alert alert-success" *ngIf="submitted">
        ✅ {{ successMessage }}
      </div>
      <div class="alert alert-danger" *ngIf="errorMessage">
        ⚠️ {{ errorMessage }}
      </div>

      <form (ngSubmit)="onSubmit()" #contactForm="ngForm">
        <div class="form-group">
          <label>Your Name *</label>
          <input type="text" [(ngModel)]="formData.name" name="name" required class="form-input" placeholder="e.g. John Doe">
        </div>
        <div class="form-group">
          <label>Your Email Address *</label>
          <input type="email" [(ngModel)]="formData.email" name="email" required class="form-input" placeholder="e.g. john@example.com">
        </div>
        <div class="form-group">
          <label>Subject</label>
          <input type="text" [(ngModel)]="formData.subject" name="subject" class="form-input" placeholder="e.g. Order Inquiry / Size Exchange">
        </div>
        <div class="form-group">
          <label>Message *</label>
          <textarea [(ngModel)]="formData.message" name="message" rows="5" required class="form-input" placeholder="Describe your query in detail..."></textarea>
        </div>
        <button type="submit" class="btn btn-primary submit-btn">Send Message</button>
      </form>
    </div>
  </div>
</div>
